        sys.stderr.write(f"Could not match '{cmd}' with any of the allowed variants: {list(OPTIONS_SCHEMA.keys())}\n")
        sys.exit(1)

    opts, pos_args = parse_cmd_args(cmd, argv[1:])

    handler_map = {
        'cat': cmd_cat,
        'count': cmd_count,
        'fixlengths': cmd_fixlengths,
        'flatten': cmd_flatten,
        'fmt': cmd_fmt,
        'frequency': cmd_frequency,
        'headers': cmd_headers,
        'index': cmd_index,
        'input': cmd_input,
        'join': cmd_join,
        'partition': cmd_partition,
        'sample': cmd_sample,
        'reverse': cmd_reverse,
        'search': cmd_search,
        'select': cmd_select,
        'slice': cmd_slice,
        'sort': cmd_sort,
        'split': cmd_split,
        'stats': cmd_stats,
        'table': cmd_table,
    }

    handler_map[cmd](opts, pos_args)

