def cmd_join(opts, pos_args):
    if len(pos_args) < 4:
        sys.stderr.write("Invalid arguments.\\n\\nUsage:\\n" + get_usage_str('join'))
        sys.exit(1)

    cols1, input1, cols2, input2 = pos_args[0], pos_args[1], pos_args[2], pos_args[3]
    redirect_stdout_if_needed(opts['output'])
    writer = get_csv_writer(sys.stdout, delimiter=opts['delimiter'])

    f1, c1 = open_file_or_stdin(input1)
    f2, c2 = open_file_or_stdin(input2)
    r1 = list(get_csv_reader(f1, delimiter=opts['delimiter']))
    r2 = list(get_csv_reader(f2, delimiter=opts['delimiter']))
    if c1: f1.close()
    if c2: f2.close()

    no_headers = opts['no_headers']
    if no_headers:
        headers1 = [str(i+1) for i in range(len(r1[0]))] if r1 else []
        headers2 = [str(i+1) for i in range(len(r2[0]))] if r2 else []
        data1 = r1
        data2 = r2
    else:
        headers1 = r1[0] if r1 else []
        headers2 = r2[0] if r2 else []
        data1 = r1[1:] if r1 else []
        data2 = r2[1:] if r2 else []

    if opts['cross']:
        writer.writerow(headers1 + headers2)
        for row1 in data1:
            for row2 in data2:
                writer.writerow(row1 + row2)
        return

    sel1 = parse_selection(cols1, headers1, no_headers)
    sel2 = parse_selection(cols2, headers2, no_headers)

    no_case = opts['no_case']
    nulls = opts['nulls']

    def get_key(row, sel):
        k = []
        for c in sel:
            v = row[c].strip() if c < len(row) else ''
            if not nulls and v == '':
                return None
            if no_case:
                v = v.lower()
            k.append(v)
        return tuple(k)

    map2 = collections.defaultdict(list)
    for row2 in data2:
        k = get_key(row2, sel2)
        if k is not None:
            map2[k].append(row2)

    writer.writerow(headers1 + headers2)
    matched2 = set()
    empty1 = [''] * len(headers1)
    empty2 = [''] * len(headers2)

    for row1 in data1:
        k1 = get_key(row1, sel1)
        matches = map2.get(k1, []) if k1 is not None else []
        if matches:
            for m in matches:
                writer.writerow(row1 + m)
                matched2.add(id(m))
        elif opts['left'] or opts['full']:
            writer.writerow(row1 + empty2)

    if opts['right'] or opts['full']:
        for row2 in data2:
            if id(row2) not in matched2:
                writer.writerow(empty1 + row2)

def cmd_partition(opts, pos_args):
    if len(pos_args) < 2:
        sys.stderr.write("Invalid arguments.\\n\\nUsage:\\n" + get_usage_str('partition'))
        sys.exit(1)

    col_spec = pos_args[0]
    outdir = pos_args[1]
    input_path = pos_args[2] if len(pos_args) > 2 else None

    os.makedirs(outdir, exist_ok=True)
    f, close = open_file_or_stdin(input_path)
    reader = get_csv_reader(f, delimiter=opts['delimiter'])
    rows = list(reader)
    if close: f.close()
    if not rows: return

    no_headers = opts['no_headers']
    if no_headers:
        headers = [str(i+1) for i in range(len(rows[0]))]
        data_rows = rows
    else:
        headers = rows[0]
        data_rows = rows[1:]

    part_col = parse_selection(col_spec, headers, no_headers)[0]
    prefix_len = int(opts['prefix_length'])
    drop = opts['drop']

    writers = {}
    files = {}

    out_headers = [h for i, h in enumerate(headers) if i != part_col] if drop else headers

    for row in data_rows:
        key_val = row[part_col] if part_col < len(row) else ''
        if prefix_len > 0:
            key_val = key_val[:prefix_len]

        safe_key = re.sub(r'[^a-zA-Z0-9_\\-]', '_', key_val)
        filename = opts['filename'].replace('{}', safe_key)

        if safe_key not in writers:
            filepath = os.path.join(outdir, filename)
            out_f = open(filepath, 'w', newline='', encoding='utf-8')
            files[safe_key] = out_f
            w = get_csv_writer(out_f, delimiter=opts['delimiter'])
            writers[safe_key] = w
            if not no_headers:
                w.writerow(out_headers)

        out_row = [v for i, v in enumerate(row) if i != part_col] if drop else row
        writers[safe_key].writerow(out_row)

    for f_obj in files.values():
        f_obj.close()

def cmd_sample(opts, pos_args):
    if not pos_args:
        sys.stderr.write("Invalid arguments.\\n\\nUsage:\\n" + get_usage_str('sample'))
        sys.exit(1)

    sample_size = int(pos_args[0])
    input_path = pos_args[1] if len(pos_args) > 1 else None

    if opts['seed'] is not None:
        random.seed(int(opts['seed']))

    redirect_stdout_if_needed(opts['output'])
    writer = get_csv_writer(sys.stdout, delimiter=opts['delimiter'])

    f, close = open_file_or_stdin(input_path)
    reader = get_csv_reader(f, delimiter=opts['delimiter'])

    no_headers = opts['no_headers']
    reservoir = []

    for i, row in enumerate(reader):
        if i == 0 and not no_headers:
            writer.writerow(row)
            continue
        idx = i if no_headers else i - 1
        if len(reservoir) < sample_size:
            reservoir.append(row)
        else:
            j = random.randint(0, idx)
            if j < sample_size:
                reservoir[j] = row

    if close: f.close()
    for row in reservoir:
        writer.writerow(row)

def cmd_reverse(opts, pos_args):
    input_path = pos_args[0] if pos_args else None
    redirect_stdout_if_needed(opts['output'])
    writer = get_csv_writer(sys.stdout, delimiter=opts['delimiter'])

    f, close = open_file_or_stdin(input_path)
    reader = get_csv_reader(f, delimiter=opts['delimiter'])
    rows = list(reader)
    if close: f.close()
    if not rows: return

    if opts['no_headers']:
        for row in reversed(rows):
            writer.writerow(row)
    else:
        writer.writerow(rows[0])
        for row in reversed(rows[1:]):
            writer.writerow(row)

def cmd_search(opts, pos_args):
    if not pos_args:
        sys.stderr.write("Invalid arguments.\\n\\nUsage:\\n" + get_usage_str('search'))
        sys.exit(1)

    pattern_str = pos_args[0]
    input_path = pos_args[1] if len(pos_args) > 1 else None

    flags = re.IGNORECASE if opts['ignore_case'] else 0
    try:
        pat = re.compile(pattern_str, flags)
    except re.error as e:
        sys.stderr.write(f"Regex error: {e}\\n")
        sys.exit(1)

    redirect_stdout_if_needed(opts['output'])
    writer = get_csv_writer(sys.stdout, delimiter=opts['delimiter'])

    f, close = open_file_or_stdin(input_path)
    reader = get_csv_reader(f, delimiter=opts['delimiter'])

    no_headers = opts['no_headers']
    selected_cols = None

    for i, row in enumerate(reader):
        if i == 0 and not no_headers:
            headers = row
            selected_cols = parse_selection(opts['select'], headers, no_headers)
            writer.writerow(row)
            continue
        if selected_cols is None:
            headers = [str(j+1) for j in range(len(row))]
            selected_cols = parse_selection(opts['select'], headers, no_headers)

        matched = any(pat.search(row[c]) for c in selected_cols if c < len(row))
        if opts['invert_match']:
            matched = not matched
        if matched:
            writer.writerow(row)

    if close: f.close()

def cmd_select(opts, pos_args):
    if not pos_args:
        sys.stderr.write("Invalid arguments.\\n\\nUsage:\\n" + get_usage_str('select'))
        sys.exit(1)

    selection_str = pos_args[0]
    input_path = pos_args[1] if len(pos_args) > 1 else None

    redirect_stdout_if_needed(opts['output'])
    writer = get_csv_writer(sys.stdout, delimiter=opts['delimiter'])

    f, close = open_file_or_stdin(input_path)
    reader = get_csv_reader(f, delimiter=opts['delimiter'])

    no_headers = opts['no_headers']
    selected_cols = None

    for i, row in enumerate(reader):
        if i == 0 and not no_headers:
            headers = row
            selected_cols = parse_selection(selection_str, headers, no_headers)
            writer.writerow([row[c] for c in selected_cols if c < len(row)])
            continue
        if selected_cols is None:
            headers = [str(j+1) for j in range(len(row))]
            selected_cols = parse_selection(selection_str, headers, no_headers)

        writer.writerow([row[c] for c in selected_cols if c < len(row)])

    if close: f.close()

def cmd_slice(opts, pos_args):
    input_path = pos_args[0] if pos_args else None

    if opts['index'] is not None:
        start = int(opts['index'])
        end = start + 1
    else:
        start = int(opts['start']) if opts['start'] is not None else 0
        if opts['len'] is not None:
            end = start + int(opts['len'])
        elif opts['end'] is not None:
            end = int(opts['end'])
        else:
            end = None

    redirect_stdout_if_needed(opts['output'])
    writer = get_csv_writer(sys.stdout, delimiter=opts['delimiter'])

    idx_data = check_index(input_path)
    no_headers = opts['no_headers']

    if idx_data is not None:
        total_records = idx_data[-1]
        data_start = 1 if not no_headers else 0
        actual_start = data_start + start
        actual_end = data_start + (end if end is not None else total_records - data_start)
        actual_end = min(actual_end, total_records)

        with open(input_path, 'r', newline='', encoding='utf-8', errors='replace') as f:
            if not no_headers and idx_data[0] < len(idx_data):
                f.seek(idx_data[0])
                line = f.readline()
                r = list(csv.reader([line], delimiter=unescape_delimiter(opts['delimiter'])))
                if r: writer.writerow(r[0])

            for record_idx in range(actual_start, actual_end):
                if record_idx < len(idx_data) - 1:
                    f.seek(idx_data[record_idx])
                    line = f.readline()
                    r = list(csv.reader([line], delimiter=unescape_delimiter(opts['delimiter'])))
                    if r: writer.writerow(r[0])
        return

    f, close = open_file_or_stdin(input_path)
    reader = get_csv_reader(f, delimiter=opts['delimiter'])

    for i, row in enumerate(reader):
        if i == 0 and not no_headers:
            writer.writerow(row)
            continue
        record_idx = i if no_headers else i - 1
        if record_idx < start:
            continue
        if end is not None and record_idx >= end:
            break
        writer.writerow(row)

    if close: f.close()

def cmd_sort(opts, pos_args):
    input_path = pos_args[0] if pos_args else None
    redirect_stdout_if_needed(opts['output'])
    writer = get_csv_writer(sys.stdout, delimiter=opts['delimiter'])

    f, close = open_file_or_stdin(input_path)
    reader = get_csv_reader(f, delimiter=opts['delimiter'])
    rows = list(reader)
    if close: f.close()
    if not rows: return

    no_headers = opts['no_headers']
    if no_headers:
        headers = [str(i+1) for i in range(len(rows[0]))]
        data_rows = rows
    else:
        headers = rows[0]
        data_rows = rows[1:]

    selected_cols = parse_selection(opts['select'], headers, no_headers)
    numeric = opts['numeric']

    def make_key(row):
        key = []
        for c in selected_cols:
            val = row[c] if c < len(row) else ''
            if numeric:
                try:
                    v = float(val)
                    key.append((1, v))
                except ValueError:
                    key.append((0, 0.0))
            else:
                key.append(val)
        return key

    data_rows.sort(key=make_key)
    if opts['reverse']:
        data_rows.reverse()

    if not no_headers:
        writer.writerow(headers)
    for row in data_rows:
        writer.writerow(row)

def cmd_split(opts, pos_args):
    if not pos_args:
        sys.stderr.write("Invalid arguments.\\n\\nUsage:\\n" + get_usage_str('split'))
        sys.exit(1)

    outdir = pos_args[0]
    input_path = pos_args[1] if len(pos_args) > 1 else None

    chunk_size = int(opts['size'])
    os.makedirs(outdir, exist_ok=True)

    f, close = open_file_or_stdin(input_path)
    reader = get_csv_reader(f, delimiter=opts['delimiter'])

    no_headers = opts['no_headers']
    header = None
    curr_writer = None
    curr_file = None
    curr_count = 0
    start_idx = 0

    for i, row in enumerate(reader):
        if i == 0 and not no_headers:
            header = row
            continue

        if curr_count == 0:
            filename = opts['filename'].replace('{}', str(start_idx))
            filepath = os.path.join(outdir, filename)
            curr_file = open(filepath, 'w', newline='', encoding='utf-8')
            curr_writer = get_csv_writer(curr_file, delimiter=opts['delimiter'])
            if header:
                curr_writer.writerow(header)

        curr_writer.writerow(row)
        curr_count += 1

        if curr_count == chunk_size:
            curr_file.close()
            curr_writer = None
            curr_file = None
            start_idx += chunk_size
            curr_count = 0

    if curr_file:
        curr_file.close()
    if close: f.close()

def cmd_stats(opts, pos_args):
    input_path = pos_args[0] if pos_args else None

    f, close = open_file_or_stdin(input_path)
    reader = get_csv_reader(f, delimiter=opts['delimiter'])
    rows = list(reader)
    if close: f.close()
    if not rows: return

    no_headers = opts['no_headers']
    if no_headers:
        headers = [str(i+1) for i in range(len(rows[0]))]
        data_rows = rows
    else:
        headers = rows[0]
        data_rows = rows[1:]

    selected_cols = parse_selection(opts['select'], headers, no_headers)
    everything = opts['everything']
    show_median = everything or opts['median']
    show_mode = everything or opts['mode']
    show_cardinality = everything or opts['cardinality']
    include_nulls = opts['nulls']

    out_headers = ['field', 'type', 'sum', 'min', 'max', 'min_length', 'max_length', 'mean', 'stddev']
    if show_median: out_headers.append('median')
    if show_mode: out_headers.append('mode')
    if show_cardinality: out_headers.append('cardinality')

    redirect_stdout_if_needed(opts['output'])
    writer = get_csv_writer(sys.stdout)
    writer.writerow(out_headers)

    for col in selected_cols:
        field_name = headers[col] if not no_headers else str(col + 1)
        col_vals = [r[col] if col < len(r) else '' for r in data_rows]

        lengths = [len(v) for v in col_vals]
        min_len = min(lengths) if lengths else 0
        max_len = max(lengths) if lengths else 0

        non_null_vals = [v for v in col_vals if v != '']

        if not non_null_vals:
            col_type = 'NULL'
        else:
            is_int = True
            is_float = True
            for v in non_null_vals:
                try:
                    int(v)
                except ValueError:
                    is_int = False
                try:
                    float(v)
                except ValueError:
                    is_float = False

            if is_int:
                col_type = 'Integer'
            elif is_float:
                col_type = 'Float'
            else:
                col_type = 'Unicode'

        sum_str, min_str, max_str, mean_str, stddev_str = '', '', '', '', ''

        if col_type in ('Integer', 'Float'):
            nums = [float(v) for v in non_null_vals]
            if include_nulls:
                nums_all = nums + [0.0] * (len(col_vals) - len(nums))
            else:
                nums_all = nums

            if nums:
                s = sum(nums)
                sum_str = str(int(s)) if col_type == 'Integer' and s.is_integer() else str(s)
                min_v = min(nums)
                max_v = max(nums)
                min_str = str(int(min_v)) if col_type == 'Integer' and min_v.is_integer() else str(min_v)
                max_str = str(int(max_v)) if col_type == 'Integer' and max_v.is_integer() else str(max_v)

                n = len(nums_all)
                if n > 0:
                    mean_v = sum(nums_all) / n
                    mean_str = str(mean_v)
                    variance = sum((x - mean_v) ** 2 for x in nums_all) / n
                    stddev_str = str(math.sqrt(variance))
        elif col_type == 'Unicode':
            if non_null_vals:
                min_str = min(non_null_vals)
                max_str = max(non_null_vals)

        res = [field_name, col_type, sum_str, min_str, max_str, str(min_len), str(max_len), mean_str, stddev_str]

        if show_median:
            median_str = ''
            if col_type in ('Integer', 'Float') and non_null_vals:
                s_nums = sorted([float(v) for v in non_null_vals])
                n = len(s_nums)
                if n % 2 == 1:
                    med = s_nums[n // 2]
                else:
                    med = (s_nums[n // 2 - 1] + s_nums[n // 2]) / 2.0
                median_str = str(int(med)) if col_type == 'Integer' and med.is_integer() else str(med)
            res.append(median_str)

        if show_mode:
            mode_str = ''
            if non_null_vals:
                counts = collections.Counter(non_null_vals)
                top = counts.most_common(2)
                if len(top) == 1 or top[0][1] > top[1][1]:
                    mode_str = top[0][0]
                else:
                    mode_str = 'N/A'
            else:
                mode_str = 'N/A'
            res.append(mode_str)

        if show_cardinality:
            res.append(str(len(set(col_vals))))

        writer.writerow(res)

def cmd_table(opts, pos_args):
    input_path = pos_args[0] if pos_args else None
    width = int(opts['width'])
    pad = int(opts['pad'])
    condense = int(opts['condense']) if opts['condense'] else None

    f, close = open_file_or_stdin(input_path)
    reader = get_csv_reader(f, delimiter=opts['delimiter'])
    rows = list(reader)
    if close: f.close()
    if not rows: return

    num_cols = max(len(r) for r in rows)
    col_widths = [width] * num_cols

    formatted_rows = []
    for row in rows:
        f_row = []
        for j in range(num_cols):
            val = row[j] if j < len(row) else ''
            if condense is not None and len(val) > condense:
                val = val[:condense] + "..."
            f_row.append(val)
            col_widths[j] = max(col_widths[j], len(val))
        formatted_rows.append(f_row)

    redirect_stdout_if_needed(opts['output'])
    for row in formatted_rows:
        line_parts = []
        for j, val in enumerate(row):
            if j < num_cols - 1:
                w = col_widths[j] + pad
                line_parts.append(val.ljust(w))
            else:
                line_parts.append(val)
        print(''.join(line_parts))

def main():
