        sys.exit(1)

    opts, pos_args = parse_cmd_args(cmd, argv[1:])

    handler_map = {
        'cat': cmd_cat,
        'count': cmd_count,
        'fixlengths': cmd_fixlengths,
        'flatten': cmd_flatten,
        'fmt': cmd_fmt,
        'frequency': cmd_frequency,
        'headers': cmd_headers,
        'index': cmd_index,
