def cmd_join(opts, pos_args):
    if len(pos_args) < 4:
        sys.stderr.write("Invalid arguments.\\n\\nUsage:\\n" + get_usage_str('join'))
        sys.exit(1)

    cols1, input1, cols2, input2 = pos_args[0], pos_args[1], pos_args[2], pos_args[3]
    redirect_stdout_if_needed(opts['output'])
    writer = get_csv_writer(sys.stdout, delimiter=opts['delimiter'])

    f1, c1 = open_file_or_stdin(input1)
    f2, c2 = open_file_or_stdin(input2)
    r1 = list(get_csv_reader(f1, delimiter=opts['delimiter']))
    r2 = list(get_csv_reader(f2, delimiter=opts['delimiter']))
    if c1: f1.close()
    if c2: f2.close()

    no_headers = opts['no_headers']
    if no_headers:
        headers1 = [str(i+1) for i in range(len(r1[0]))] if r1 else []
        headers2 = [str(i+1) for i in range(len(r2[0]))] if r2 else []
        data1 = r1
        data2 = r2
    else:
        headers1 = r1[0] if r1 else []
        headers2 = r2[0] if r2 else []
        data1 = r1[1:] if r1 else []
        data2 = r2[1:] if r2 else []

    if opts['cross']:
        writer.writerow(headers1 + headers2)
        for row1 in data1:
            for row2 in data2:
                writer.writerow(row1 + row2)
        return

    sel1 = parse_selection(cols1, headers1, no_headers)
    sel2 = parse_selection(cols2, headers2, no_headers)

    no_case = opts['no_case']
    nulls = opts['nulls']

    def get_key(row, sel):
        k = []
        for c in sel:
            v = row[c].strip() if c < len(row) else ''
            if not nulls and v == '':
                return None
            if no_case:
                v = v.lower()
            k.append(v)
        return tuple(k)

    map2 = collections.defaultdict(list)
    for row2 in data2:
        k = get_key(row2, sel2)
        if k is not None:
            map2[k].append(row2)

    writer.writerow(headers1 + headers2)
    matched2 = set()
    empty1 = [''] * len(headers1)
    empty2 = [''] * len(headers2)

    for row1 in data1:
        k1 = get_key(row1, sel1)
        matches = map2.get(k1, []) if k1 is not None else []
        if matches:
            for m in matches:
                writer.writerow(row1 + m)
                matched2.add(id(m))
        elif opts['left'] or opts['full']:
            writer.writerow(row1 + empty2)

    if opts['right'] or opts['full']:
        for row2 in data2:
            if id(row2) not in matched2:
                writer.writerow(empty1 + row2)

def cmd_partition(opts, pos_args):
    if len(pos_args) < 2:
        sys.stderr.write("Invalid arguments.\\n\\nUsage:\\n" + get_usage_str('partition'))
        sys.exit(1)

    col_spec = pos_args[0]
    outdir = pos_args[1]
    input_path = pos_args[2] if len(pos_args) > 2 else None

    os.makedirs(outdir, exist_ok=True)
    f, close = open_file_or_stdin(input_path)
    reader = get_csv_reader(f, delimiter=opts['delimiter'])
    rows = list(reader)
    if close: f.close()
    if not rows: return

    no_headers = opts['no_headers']
    if no_headers:
        headers = [str(i+1) for i in range(len(rows[0]))]
        data_rows = rows
    else:
        headers = rows[0]
        data_rows = rows[1:]

    part_col = parse_selection(col_spec, headers, no_headers)[0]
    prefix_len = int(opts['prefix_length'])
    drop = opts['drop']

    writers = {}
    files = {}

    out_headers = [h for i, h in enumerate(headers) if i != part_col] if drop else headers

    for row in data_rows:
        key_val = row[part_col] if part_col < len(row) else ''
        if prefix_len > 0:
            key_val = key_val[:prefix_len]

        safe_key = re.sub(r'[^a-zA-Z0-9_\\-]', '_', key_val)
        filename = opts['filename'].replace('{}', safe_key)

        if safe_key not in writers:
            filepath = os.path.join(outdir, filename)
            out_f = open(filepath, 'w', newline='', encoding='utf-8')
            files[safe_key] = out_f
            w = get_csv_writer(out_f, delimiter=opts['delimiter'])
            writers[safe_key] = w
            if not no_headers:
                w.writerow(out_headers)

        out_row = [v for i, v in enumerate(row) if i != part_col] if drop else row
        writers[safe_key].writerow(out_row)

    for f_obj in files.values():
        f_obj.close()

def cmd_sample(opts, pos_args):
    if not pos_args:
        sys.stderr.write("Invalid arguments.\\n\\nUsage:\\n" + get_usage_str('sample'))
        sys.exit(1)

    sample_size = int(pos_args[0])
    input_path = pos_args[1] if len(pos_args) > 1 else None

    if opts['seed'] is not None:
        random.seed(int(opts['seed']))

    redirect_stdout_if_needed(opts['output'])
    writer = get_csv_writer(sys.stdout, delimiter=opts['delimiter'])

    f, close = open_file_or_stdin(input_path)
    reader = get_csv_reader(f, delimiter=opts['delimiter'])

    no_headers = opts['no_headers']
    reservoir = []

    for i, row in enumerate(reader):
        if i == 0 and not no_headers:
            writer.writerow(row)
            continue
        idx = i if no_headers else i - 1
        if len(reservoir) < sample_size:
            reservoir.append(row)
        else:
            j = random.randint(0, idx)
            if j < sample_size:
                reservoir[j] = row

    if close: f.close()
    for row in reservoir:
        writer.writerow(row)

