def cmd_frequency(opts, pos_args):
    input_path = pos_args[0] if pos_args else None
    no_headers = opts['no_headers']
    no_nulls = opts['no_nulls']
    limit = int(opts['limit'])
    asc = opts['asc']

    f, close = open_file_or_stdin(input_path)
    reader = get_csv_reader(f, delimiter=opts['delimiter'])
    rows = list(reader)
    if close:
        f.close()
    if not rows:
        return

    if no_headers:
        headers = [str(i+1) for i in range(len(rows[0]))]
        data_rows = rows
    else:
        headers = rows[0]
        data_rows = rows[1:]

    selected_cols = parse_selection(opts['select'], headers, no_headers)
    redirect_stdout_if_needed(opts['output'])
    writer = get_csv_writer(sys.stdout)
    writer.writerow(['field', 'value', 'count'])

    for col in selected_cols:
        field_name = headers[col] if not no_headers else str(col + 1)
        counts = collections.Counter()
        for row in data_rows:
            val = row[col] if col < len(row) else ''
            if val == '' and no_nulls:
                continue
            if val == '':
                val = '(NULL)'
            counts[val] += 1

        items = list(counts.items())
        if not asc:
            items.sort(key=lambda x: -x[1])
        else:
            items.sort(key=lambda x: x[1])
            items.reverse()

        if limit > 0:
            items = items[:limit]

        for val, count in items:
            writer.writerow([field_name, val, count])

def cmd_headers(opts, pos_args):
    inputs = pos_args if pos_args else [None]
    just_names = opts['just_names'] or len(inputs) > 1
    intersect = opts['intersect']

    if intersect:
        seen = set()
        headers_list = []
        for inp in inputs:
            f, close = open_file_or_stdin(inp)
            reader = get_csv_reader(f, delimiter=opts['delimiter'])
            try:
                row = next(reader)
                for h in row:
                    if h not in seen:
                        seen.add(h)
                        headers_list.append(h)
            except StopIteration:
                pass
            if close:
                f.close()
        for h in headers_list:
            print(h)
    else:
        for inp in inputs:
            f, close = open_file_or_stdin(inp)
            reader = get_csv_reader(f, delimiter=opts['delimiter'])
            try:
                row = next(reader)
                if just_names:
                    for h in row:
                        print(h)
                else:
                    for i, h in enumerate(row, 1):
                        print(f"{i:<4}{h}")
            except StopIteration:
                pass
            if close:
                f.close()

def cmd_index(opts, pos_args):
    if not pos_args:
        sys.stderr.write("Invalid arguments.\\n\\nUsage:\\n" + get_usage_str('index'))
        sys.exit(1)
    input_path = pos_args[0]
    output_path = opts['output'] if opts['output'] else input_path + '.idx'

    try:
        f = open(input_path, 'rb')
    except OSError as e:
        sys.stderr.write(f"failed to open {input_path}: {e.strerror} (os error {e.errno})\\n")
        sys.exit(1)

    offsets = [0]
    total_records = 0

    while True:
        line = f.readline()
        if not line:
            break
        total_records += 1
        offsets.append(f.tell())

    f.close()

    offsets.pop()
    offsets.append(total_records)

    with open(output_path, 'wb') as out_f:
        for off in offsets:
            out_f.write(struct.pack('>Q', off))

