        return

    sel1 = parse_selection(cols1, headers1, no_headers)
    sel2 = parse_selection(cols2, headers2, no_headers)

    no_case = opts['no_case']
    nulls = opts['nulls']

    def get_key(row, sel):
        k = []
        for c in sel:
            v = row[c].strip() if c < len(row) else ''
            if not nulls and v == '':
                return None
            if no_case:
                v = v.lower()
            k.append(v)
        return tuple(k)

    map2 = collections.defaultdict(list)
    for row2 in data2:
        k = get_key(row2, sel2)
        if k is not None:
            map2[k].append(row2)

    writer.writerow(headers1 + headers2)
    matched2 = set()
    empty1 = [''] * len(headers1)
    empty2 = [''] * len(headers2)

    for row1 in data1:
        k1 = get_key(row1, sel1)
        matches = map2.get(k1, []) if k1 is not None else []
        if matches:
            for m in matches:
