def get_usage_str(cmd):
    text = HELP_TEXTS.get(cmd, '')
    if "Usage:" in text:
        idx = text.index("Usage:")
        lines = text[idx:].splitlines()
        usage_lines = []
        for line in lines:
            if usage_lines and line == "":
                break
            usage_lines.append(line)
        return "\\n".join(usage_lines) + "\\n"
    return text

def parse_cmd_args(cmd, argv):
    if '-h' in argv or '--help' in argv:
        sys.stdout.write(HELP_TEXTS[cmd])
        sys.exit(0)

    schema = OPTIONS_SCHEMA[cmd]
    bools = schema['bools']
    values = schema['values']
    opts = dict(schema['defaults'])
    pos_args = []

    i = 0
    double_dash = False
    while i < len(argv):
        arg = argv[i]
        if double_dash:
            pos_args.append(arg)
            i += 1
            continue
        if arg == '--':
            double_dash = True
            i += 1
            continue
        if arg.startswith('-') and len(arg) > 1:
            if arg in bools:
                opts[bools[arg]] = True
                i += 1
            elif arg in values:
                if i + 1 < len(argv):
                    opts[values[arg]] = argv[i + 1]
                    i += 2
                else:
                    sys.stderr.write(f"Flag {arg} requires a value.\\n\\nUsage:\\n" + get_usage_str(cmd))
                    sys.exit(1)
            elif '=' in arg:
                flag, val = arg.split('=', 1)
                if flag in values:
                    opts[values[flag]] = val
                    i += 1
                else:
                    sys.stderr.write(f"Unknown flag: '{flag}'\\n\\n" + get_usage_str(cmd))
                    sys.exit(1)
            elif len(arg) > 2 and arg[:2] in values:
                flag = arg[:2]
                val = arg[2:]
                opts[values[flag]] = val
                i += 1
            else:
                sys.stderr.write(f"Unknown flag: '{arg}'\\n\\n" + get_usage_str(cmd))
                sys.exit(1)
        else:
            pos_args.append(arg)
            i += 1

    return opts, pos_args

def unescape_delimiter(d):
    if d == r'\\t' or d == '\\t':
        return '\\t'
    if d == r'\\n' or d == '\\n':
        return '\\n'
    if d == r'\\r' or d == '\\r':
        return '\\r'
    if d == r'\\0' or d == '\\0':
        return '\\0'
    return d

def redirect_stdout_if_needed(output_path):
    if output_path:
        try:
            f = open(output_path, 'w', newline='', encoding='utf-8')
            sys.stdout = f
            return f
        except OSError as e:
            sys.stderr.write(f"failed to open {output_path}: {e.strerror} (os error {e.errno})\\n")
            sys.exit(1)
    return None

def open_file_or_stdin(path):
    if not path or path == '-':
        return sys.stdin, False
    try:
        f = open(path, 'r', newline='', encoding='utf-8', errors='replace')
        return f, True
    except OSError as e:
        sys.stderr.write(f"failed to open {path}: {e.strerror} (os error {e.errno})\\n")
        sys.exit(1)

def get_csv_reader(f, delimiter=',', quote='"', escape=None, no_quoting=False):
    delim = unescape_delimiter(delimiter)
    quoting = csv.QUOTE_NONE if no_quoting else csv.QUOTE_MINIMAL
    escapechar = escape if escape else None
    quotechar = quote if quote else '"'
    return csv.reader(f, delimiter=delim, quotechar=quotechar, escapechar=escapechar, quoting=quoting)

def get_csv_writer(f=sys.stdout, delimiter=',', quote='"', escape=None, crlf=False, ascii_mode=False, quote_always=False):
    if ascii_mode:
        delim = '\\x1f'
        lineterminator = '\\x1e'
        quotechar = '"'
        quoting = csv.QUOTE_NONE
    else:
        delim = unescape_delimiter(delimiter)
        lineterminator = '\\r\\n' if crlf else '\\n'
        quotechar = quote if quote else '"'
        quoting = csv.QUOTE_ALL if quote_always else csv.QUOTE_MINIMAL

    escapechar = escape if escape else None
    return csv.writer(f, delimiter=delim, quotechar=quotechar, escapechar=escapechar, quoting=quoting, lineterminator=lineterminator)

def check_index(csv_path):
    if not csv_path or csv_path == '-':
        return None
    idx_path = csv_path + '.idx'
    if os.path.isfile(idx_path):
        try:
            csv_stat = os.stat(csv_path)
            idx_stat = os.stat(idx_path)
            if csv_stat.st_mtime > idx_stat.st_mtime:
                sys.stderr.write("The CSV file was modified after the index file. Please re-create the index.\\n")
                sys.exit(1)
            with open(idx_path, 'rb') as f:
                data = f.read()
            nums = struct.unpack(f'>{len(data)//8}Q', data)
            return nums
        except OSError:
            pass
    return None

def resolve_single_selector(token, headers, no_headers, is_start=True):
    num_cols = len(headers)
    if not token:
        return 0 if is_start else num_cols - 1

    try:
        val = int(token)
        if val < 0:
            idx = num_cols + val
        else:
            idx = val - 1
        if idx < 0 or idx >= num_cols:
            sys.stderr.write(f"Selector index {val} is out of bounds. Index must be >= 1 and <= {num_cols}.\\n")
            sys.exit(1)
        return idx
    except ValueError:
        pass

    if no_headers:
        sys.stderr.write(f"Selector name '{token}' does not exist as a named header in the given CSV data.\\n")
        sys.exit(1)

    m = re.match(r'^(.*)\\[(\\d+)\\]$', token)
    if m:
        name, k_str = m.group(1), int(m.group(2))
        matches = [i for i, h in enumerate(headers) if h == name]
        if k_str < len(matches):
            return matches[k_str]
        sys.stderr.write(f"Selector name '{token}' does not exist as a named header in the given CSV data.\\n")
        sys.exit(1)

    for i, h in enumerate(headers):
        if h == token:
            return i

    sys.stderr.write(f"Selector name '{token}' does not exist as a named header in the given CSV data.\\n")
    sys.exit(1)

def parse_selection(selection_str, headers, no_headers=False):
    num_cols = len(headers) if headers else 0
    if not selection_str:
        return list(range(num_cols))

    selection_str = selection_str.strip()
    is_negated = selection_str.startswith('!')
    if is_negated:
        selection_str = selection_str[1:]

    tokens = []
    current = []
    in_quotes = False
    for char in selection_str:
        if char == '"':
            in_quotes = not in_quotes
            current.append(char)
        elif char == ',' and not in_quotes:
            tokens.append(''.join(current).strip())
            current = []
        else:
            current.append(char)
    if current:
        tokens.append(''.join(current).strip())

    selected = []
    for token in tokens:
        if not token:
            continue
        if token.startswith('"') and token.endswith('"') and len(token) >= 2:
            token = token[1:-1]

        if '-' in token and not (token.startswith('-') and token[1:].isdigit()):
            parts = token.split('-', 1)
            start_str, end_str = parts[0].strip(), parts[1].strip()
            start_idx = resolve_single_selector(start_str, headers, no_headers, is_start=True)
            end_idx = resolve_single_selector(end_str, headers, no_headers, is_start=False)
            if start_idx <= end_idx:
                selected.extend(range(start_idx, end_idx + 1))
            else:
                selected.extend(range(start_idx, end_idx - 1, -1))
        else:
            idx = resolve_single_selector(token, headers, no_headers)
            selected.append(idx)

    if is_negated:
        neg_set = set(selected)
        return [i for i in range(num_cols) if i not in neg_set]
    return selected

# Subcommand implementations

def cmd_cat(opts, pos_args):
    if not pos_args or pos_args[0] not in ('rows', 'columns'):
        sys.stderr.write("Invalid arguments.\\n\\nUsage:\\n" + get_usage_str('cat'))
        sys.exit(1)

    mode = pos_args[0]
    inputs = pos_args[1:] if len(pos_args) > 1 else [None]
    redirect_stdout_if_needed(opts['output'])
    writer = get_csv_writer(sys.stdout, delimiter=opts['delimiter'])

    if mode == 'rows':
        no_headers = opts['no_headers']
        first_cols = None
        for idx, in_path in enumerate(inputs):
            f, close = open_file_or_stdin(in_path)
            reader = get_csv_reader(f, delimiter=opts['delimiter'])
            for row_idx, row in enumerate(reader):
                if first_cols is None:
                    first_cols = len(row)
                elif len(row) != first_cols:
                    sys.stdout.flush()
                    sys.stderr.write(f"{','.join(row)}CSV error: found record with {len(row)} fields, but the previous record has {first_cols} fields\\n")
                    sys.exit(1)

                if row_idx == 0:
                    if not no_headers:
                        if idx == 0:
                            writer.writerow(row)
                    else:
                        writer.writerow(row)
                else:
                    writer.writerow(row)
            if close:
                f.close()
    else: # columns
        pad = opts['pad']
        files_and_closes = [open_file_or_stdin(p) for p in inputs]
        readers = [get_csv_reader(fc[0], delimiter=opts['delimiter']) for fc in files_and_closes]

        while True:
            rows = []
            active = False
            for r in readers:
                try:
                    row = next(r)
                    active = True
                except StopIteration:
                    row = None
                rows.append(row)

            if not pad and None in rows:
                break
            if pad and not active:
                break

            combined = []
            for i, r in enumerate(rows):
                if r is not None:
                    combined.extend(r)
                else:
                    combined.extend([]) # padded empty fields
            writer.writerow(combined)

        for fc in files_and_closes:
            if fc[1]:
                fc[0].close()

def cmd_count(opts, pos_args):
    input_path = pos_args[0] if pos_args else None
    no_headers = opts['no_headers']

    idx_data = check_index(input_path)
    if idx_data is not None:
        total = idx_data[-1]
        cnt = total if no_headers else max(0, total - 1)
        print(cnt)
        return

    f, close = open_file_or_stdin(input_path)
    reader = get_csv_reader(f, delimiter=opts['delimiter'])
    total = sum(1 for _ in reader)
    if close:
        f.close()
    cnt = total if no_headers else max(0, total - 1)
    print(cnt)

def cmd_fixlengths(opts, pos_args):
    input_path = pos_args[0] if pos_args else None
    redirect_stdout_if_needed(opts['output'])
    writer = get_csv_writer(sys.stdout, delimiter=opts['delimiter'])

    if opts['length'] is not None:
        target_len = int(opts['length'])
        f, close = open_file_or_stdin(input_path)
        reader = get_csv_reader(f, delimiter=opts['delimiter'])
        for row in reader:
            if len(row) < target_len:
                row = row + [''] * (target_len - len(row))
            else:
                row = row[:target_len]
            writer.writerow(row)
        if close:
            f.close()
    else:
        if not input_path or input_path == '-':
            sys.stderr.write("fixlengths requires a file input when --length is not set\\n")
            sys.exit(1)
        f, close = open_file_or_stdin(input_path)
        reader = get_csv_reader(f, delimiter=opts['delimiter'])
        max_len = 1
        for row in reader:
            while row and row[-1] == '':
                row.pop()
            max_len = max(max_len, len(row))
        if close:
            f.close()

        f, close = open_file_or_stdin(input_path)
        reader = get_csv_reader(f, delimiter=opts['delimiter'])
        for row in reader:
            if len(row) < max_len:
                row = row + [''] * (max_len - len(row))
            else:
                row = row[:max_len]
            writer.writerow(row)
        if close:
            f.close()

def cmd_flatten(opts, pos_args):
    input_path = pos_args[0] if pos_args else None
    condense = int(opts['condense']) if opts['condense'] else None
    separator = opts['separator']
    no_headers = opts['no_headers']

    f, close = open_file_or_stdin(input_path)
    reader = get_csv_reader(f, delimiter=opts['delimiter'])
    rows = list(reader)
    if close:
        f.close()
    if not rows:
        return

    if no_headers:
        headers = [str(i) for i in range(len(rows[0]))]
        data_rows = rows
    else:
        headers = rows[0]
        data_rows = rows[1:]

    max_h_len = max(len(h) for h in headers) if headers else 0
    pad_width = max_h_len + 2

    for row in data_rows:
        for i, val in enumerate(row):
            h_str = headers[i] if i < len(headers) else str(i)
            if condense is not None and len(val) > condense:
                val = val[:condense] + "..."
            print(f"{h_str:<{pad_width}}{val}")
        if separator:
            print(separator)

def cmd_fmt(opts, pos_args):
    input_path = pos_args[0] if pos_args else None
    redirect_stdout_if_needed(opts['output'])
    writer = get_csv_writer(sys.stdout, delimiter=opts['out_delimiter'], crlf=opts['crlf'], ascii_mode=opts['ascii'], quote=opts['quote'], quote_always=opts['quote_always'], escape=opts['escape'])
    f, close = open_file_or_stdin(input_path)
    reader = get_csv_reader(f, delimiter=opts['delimiter'])
    for row in reader:
        writer.writerow(row)
    if close:
        f.close()

def cmd_frequency(opts, pos_args):
    input_path = pos_args[0] if pos_args else None
    no_headers = opts['no_headers']
    no_nulls = opts['no_nulls']
    limit = int(opts['limit'])
    asc = opts['asc']

    f, close = open_file_or_stdin(input_path)
    reader = get_csv_reader(f, delimiter=opts['delimiter'])
    rows = list(reader)
    if close:
        f.close()
    if not rows:
        return

    if no_headers:
        headers = [str(i+1) for i in range(len(rows[0]))]
        data_rows = rows
    else:
        headers = rows[0]
        data_rows = rows[1:]

    selected_cols = parse_selection(opts['select'], headers, no_headers)
    redirect_stdout_if_needed(opts['output'])
    writer = get_csv_writer(sys.stdout)
    writer.writerow(['field', 'value', 'count'])

    for col in selected_cols:
        field_name = headers[col] if not no_headers else str(col + 1)
        counts = collections.Counter()
        for row in data_rows:
            val = row[col] if col < len(row) else ''
            if val == '' and no_nulls:
                continue
            if val == '':
                val = '(NULL)'
            counts[val] += 1

        items = list(counts.items())
        if not asc:
            items.sort(key=lambda x: -x[1])
        else:
            items.sort(key=lambda x: x[1])
            items.reverse()

        if limit > 0:
            items = items[:limit]

        for val, count in items:
            writer.writerow([field_name, val, count])

def cmd_headers(opts, pos_args):
    inputs = pos_args if pos_args else [None]
    just_names = opts['just_names'] or len(inputs) > 1
    intersect = opts['intersect']

    if intersect:
        seen = set()
        headers_list = []
        for inp in inputs:
            f, close = open_file_or_stdin(inp)
            reader = get_csv_reader(f, delimiter=opts['delimiter'])
            try:
                row = next(reader)
                for h in row:
                    if h not in seen:
                        seen.add(h)
                        headers_list.append(h)
            except StopIteration:
                pass
            if close:
                f.close()
        for h in headers_list:
            print(h)
    else:
        for inp in inputs:
            f, close = open_file_or_stdin(inp)
            reader = get_csv_reader(f, delimiter=opts['delimiter'])
            try:
                row = next(reader)
                if just_names:
                    for h in row:
                        print(h)
                else:
                    for i, h in enumerate(row, 1):
                        print(f"{i:<4}{h}")
            except StopIteration:
                pass
            if close:
                f.close()

def cmd_index(opts, pos_args):
    if not pos_args:
        sys.stderr.write("Invalid arguments.\\n\\nUsage:\\n" + get_usage_str('index'))
        sys.exit(1)
    input_path = pos_args[0]
    output_path = opts['output'] if opts['output'] else input_path + '.idx'

    try:
        f = open(input_path, 'rb')
    except OSError as e:
        sys.stderr.write(f"failed to open {input_path}: {e.strerror} (os error {e.errno})\\n")
        sys.exit(1)

    offsets = [0]
    total_records = 0

    while True:
        line = f.readline()
        if not line:
            break
        total_records += 1
        offsets.append(f.tell())

    f.close()

    offsets.pop()
    offsets.append(total_records)

    with open(output_path, 'wb') as out_f:
        for off in offsets:
            out_f.write(struct.pack('>Q', off))

def cmd_input(opts, pos_args):
    input_path = pos_args[0] if pos_args else None
